 const own=document.createElement('dialog');own.id='method-decision-dialog';own.setAttribute('aria-label','方法标签与已有正文');document.body.append(own);
 const dialogStyle=document.createElement('style');dialogStyle.textContent="#method-decision-dialog{width:min(1000px,94vw);max-height:92dvh;padding:0;border:1px solid #ccd7e3;border-radius:12px}#method-decision-dialog::backdrop{background:#132b4960}";document.head.append(dialogStyle);
 const stack=[];let callerSelector=null,callerSearch=null,methodHop=null;
 const contentCache=new Map(),loads=new Map();
 function selector(el){for(const key of ['data-ui-key','data-method-reference','data-r80-evidence','data-method-label'])if(el?.hasAttribute(key))return '['+key+'="'+CSS.escape(el.getAttribute(key))+'"]';return el?.id?'#'+CSS.escape(el.id):null;}
 function focus(key,root=document){root.querySelector(key||'#__no_method_entry__')?.focus({preventScroll:true});}
 function close(){if(stack.length){const old=stack.pop();own.innerHTML=old.html;own.scrollTop=old.scroll;focus(old.focus,own);return;}own.close();if(callerSearch)window.KnowledgeSearchNavigation.restore(callerSearch,callerSelector);else focus(callerSelector);}
 function push(trigger){if(own.open)stack.push({html:own.innerHTML,scroll:own.scrollTop,focus:selector(trigger)});else{callerSelector=selector(trigger);callerSearch=trigger?.matches('[data-method-label-search],[data-method-application-search],[data-method-exercise-search]')?window.KnowledgeSearchNavigation.capture():null;}}
 function show(html){own.innerHTML='<div class="r80-source-shell"><button type="button" data-method-close aria-label="返回方法入口">关闭</button>'+html+'</div>';if(!own.open)own.showModal();own.querySelector('[data-method-close]').focus();}
 // Normalize only the known full-width formula boundary for display; raw provenance stays intact.
 function sourceTitle(title){return text(title.replace('y=Asin（ωx+φ）','y=Asin(ωx+φ)'));}
 function chapterButtons(placements,scope){const ids=[...new Set(placements.flatMap(x=>x.chapterIds))];return '<section class="textbook-section"><h3>来源教案对应章节</h3><div class="r80-example-links">'+ids.map(id=>'<button type="button" data-method-chapter="'+esc(id)+'" data-ui-key="B05-chapter:'+esc(scope)+':'+esc(id)+'">'+esc(node(id).bookIds.map(b=>node(b)?.name).join(' / ')+' · '+node(id).name)+'</button>').join('')+'</div><details><summary>查看教案与章节对应</summary>'+placements.map(x=>'<p data-source-id="'+esc(x.sourceId)+'" data-source-title="'+esc(x.sourceTitle)+'">'+esc(x.sourceId)+' · '+sourceTitle(x.sourceTitle)+'<br>'+esc(x.chapterIds.map(id=>node(id).name).join(' / '))+'</p>').join('')+'</details></section>';}
 function referenceButtons(refs,scope){return '<div class="r80-example-links">'+refs.map(r=>'<button type="button" data-method-reference="'+esc(r.contentId)+'" data-ui-key="B05-reference:'+esc(scope)+':'+esc(r.contentId)+'">'+text(r.title)+' <small>'+esc(r.sourceIds.join(' / '))+'</small></button>').join('')+'</div>';}
 const labelRoles=window.MethodNavigation.roles;
 function nodeButtons(nodes,scope){return '<div class="method-nav-links">'+nodes.map(n=>'<button type="button" data-method-node="'+esc(n.id)+'" data-ui-key="S34-node:'+esc(scope)+':'+esc(n.id)+'">'+text(n.name)+'<small>'+esc(window.MethodNavigation.role(n))+'</small></button>').join('')+'</div>';}
 function organizationBlock(id){const g=window.MethodNavigation.organization(id);if(!g)return '';const pending=g.pending.includes(id);return '<aside class="reader-organization" data-organization="'+esc(g.id)+'"><strong>'+esc(g.name)+' · 教学组织</strong><p>'+esc(g.basis)+'</p>'+(pending?'<p>本条教材／教案依据尚未取得，保留现有知识点，来源待核。</p>':'')+nodeButtons(g.members.filter(nid=>nid!==id).map(node).filter(Boolean),'organization:'+id)+'</aside>';}
 function navigationBlock(id){const nav=window.MethodNavigation,r=nav.related(id),family=node(id)?.type==='METHOD_FAMILY',members=family?nav.members(id):[];
  const group=(title,rows,scope,note='')=>rows.length?'<h4>'+esc(title)+'</h4>'+(note?'<p class="method-nav-note">'+esc(note)+'</p>':'')+nodeButtons(rows,scope):'';
  const thought=((r.thoughts||[]).length?'<h4>相关数学思想</h4><div class="method-nav-links">'+r.thoughts.map(r=>'<button type="button" data-method-node="'+esc(r.node.id)+'">'+esc(r.node.name)+'<small>'+esc(r.direct?'直接体现':('通过：'+r.viaMethodIds.map(id=>node(id).name).join('、')))+'</small></button>').join('')+'</div>':'')+(r.labels.length?'<h4>思维过程与研究策略</h4><div class="method-nav-links">'+r.labels.map(l=>'<button type="button" data-method-label="'+esc(l.id)+'" data-ui-key="B05-label:'+esc(id)+':'+esc(l.id)+'">'+esc(l.name)+'<small>'+esc(labelRoles[l.id]||l.role)+'</small></button>').join('')+'</div>':'');
  const apps=r.applications.length?'<h4>知识下的证明与应用</h4><div class="method-nav-links">'+r.applications.map(a=>{const ref=a.primaryContentId||a.references?.[0]?.contentId;return ref?'<button type="button" data-method-reference="'+esc(ref)+'" data-method-application-search="'+esc(a.id)+'" data-ui-key="S34-application:'+esc(id)+':'+esc(a.id)+'">'+text(a.name)+'<small>'+esc(a.decisionDisplayRole||applicationBadge(a))+'</small></button>':'';}).join('')+'</div>':'';
  const body=thought+group('具体方法与能力',r.methods,id)+group('使用本方法的知识',r.knowledge,id)+group('相关方法族',r.families,id,'按已有家族归属列出，可继续查看具体分支。')+apps+(family?group('具体方法',members.filter(n=>n.type==='METHOD'&&nav.concrete(n)),id)+group('应用能力',members.filter(n=>n.type==='SKILL'),id)+group('相关知识与知识下应用',members.filter(n=>!nav.concrete(n)),id,'保留各条目原有身份；知识点中的证明或应用可在其详情中阅读。'):'');
  return body?'<section class="reader-method-navigation" data-ui-key="S34-navigation:'+esc(id)+'"><h3 tabindex="-1">思想与方法联系</h3>'+body+'</section>':family?'<section class="reader-method-navigation"><h3>方法族</h3><p>当前尚未记录具体分支。</p></section>':'';
 }
 function navigationSummary(id){const r=window.MethodNavigation.related(id),family=node(id)?.type==='METHOD_FAMILY',count=(r.thoughts?.length||0)+r.labels.length+r.methods.length+r.knowledge.length+r.families.length+r.applications.length+(family?window.MethodNavigation.members(id).length:0);return (methodHop?.target===id?'<button type="button" data-method-return data-ui-key="S34-return:'+esc(id)+'">返回原入口</button>':'')+organizationBlock(id)+(count?'<div class="reader-method-summary"><p>思想与方法 · '+[r.thoughts?.length?r.thoughts.length+' 个数学思想':'',r.labels.length?r.labels.length+' 项思维过程与策略':'',r.methods.length?r.methods.length+' 项具体方法与能力':'',r.families.length?r.families.length+' 个相关方法族':'',family?window.MethodNavigation.members(id).length+' 个已有分支':'',r.applications.length?r.applications.length+' 项知识应用':''].filter(Boolean).join(' · ')+'</p><button type="button" data-jump="reader-method-navigation" data-ui-key="S34-summary:'+esc(id)+'">查看联系</button></div>':'');}
 function labelConnections(id){const rows=window.MethodNavigation.labelNodes(id),knowledge=rows.filter(n=>n.type==='KNOWLEDGE'),methods=rows.filter(n=>window.MethodNavigation.concrete(n)),chapters=rows.filter(n=>n.type==='CHAPTER');return '<section class="method-navigation-index" data-label-connections="'+esc(id)+'"><h3>跨知识点联系</h3><p class="method-nav-note">点击已有联系，查看这一过程或策略在知识学习与解题中的应用。</p>'+(knowledge.length?nodeButtons(knowledge,id):'<p>尚未记录知识点关联。</p>')+(methods.length?'<h3>已有具体方法</h3>'+nodeButtons(methods,id):'')+(chapters.length?'<h3>相关章节</h3><div class="method-nav-links">'+chapters.map(n=>'<button type="button" data-method-chapter="'+esc(n.id)+'" data-ui-key="S34-label-chapter:'+esc(id)+':'+esc(n.id)+'">'+text(n.name)+'</button>').join('')+'</div>':'')+'</section>';}
 function openNavigationIndex(trigger){const nav=window.MethodNavigation;push(trigger);show('<section class="method-navigation-index"><h2>思想与方法</h2><p>六大思想横向联系知识与方法；方法族用于组织具体方法。</p><h3>六大数学思想</h3>'+nodeButtons(window.ThoughtTaxonomy.thoughts,'six-thoughts')+'<h3>思维过程、研究策略与专题观念</h3><div class="method-nav-links">'+nav.labels().map(l=>'<button type="button" data-method-label="'+esc(l.id)+'" data-ui-key="S34-index-label:'+esc(l.id)+'">'+esc(l.name)+'<small>'+esc(labelRoles[l.id])+' · '+nav.labelNodes(l.id).length+' 个已有联系</small></button>').join('')+'</div><h3>方法族</h3>'+nodeButtons(nav.families(),'index')+'</section>');}
 function labelBlock(id){return navigationBlock(id);}

 function applicationBadge(a){return a.decisionDisplayRole|| (a.status==='user_decided_application_branch'?'已确定的应用分支':'既有知识应用 · 候选身份保留');}
 function applicationProcedure(a){return (a.procedure?.length?'<ol class="r80-method-steps">'+a.procedure.map(step=>'<li>'+text(step)+'</li>').join('')+'</ol>':'')+(a.relatedExistingNodeIds?.length?'<h4>相关知识与可选工具</h4><div class="r80-example-links">'+a.relatedExistingNodeIds.map(id=>'<button type="button" data-method-node="'+esc(id)+'" data-ui-key="DOT-R7-application-tool:'+esc(a.id)+':'+esc(id)+'">'+text(node(id).name)+'</button>').join('')+'</div>':'');}
 function applicationBlock(id){const apps=Object.values(decisions.applicationBranches||{}).filter(a=>a.nodeIds.includes(id)&&!decisions.DOTR24D7KnowledgeEntries?.[a.id]);if(!apps.length)return '';const title=apps.every(a=>a.status==='user_decided_application_branch')?'已确定的应用分支':'具名应用与方案';return '<section class="reader-application-branches" aria-label="'+title+'"><h3>'+title+'</h3>'+apps.map(a=>'<details data-application-id="'+esc(a.id)+'" data-ui-key="B14-application:'+esc(id)+':'+esc(a.id)+'"><summary><b>'+esc(a.name)+'</b><small>'+esc(applicationBadge(a))+'</small></summary><p class="r80-note">'+text(a.readingNote)+'</p>'+applicationProcedure(a)+referenceButtons(a.references,a.id)+chapterButtons(a.sourceChapterPlacements,a.id)+'</details>').join('')+'</section>';}
 function d7KnowledgeBlock(id){const entries=Object.values(decisions.DOTR24D7KnowledgeEntries||{}).filter(a=>a.nodeIds.includes(id));return entries.length?'<section class="reader-knowledge-procedures" aria-label="知识下的证明路线与应用">'+entries.map(a=>'<article data-d7-knowledge-entry="'+esc(a.id)+'"><h3>'+esc(a.decisionDisplayRole)+'</h3><h4>'+text(a.name)+'</h4><p class="r80-note">'+text(a.readingNote)+'</p>'+applicationProcedure(a)+(a.displayKind==='named_application'?'':referenceButtons(a.references,a.id)+chapterButtons(a.sourceChapterPlacements,a.id))+'</article>').join('')+'</section>':'';}
 function distanceOverview(id){const d=decisions.distanceSections[id];return '<div class="reader-overview"><p class="reader-description">'+text(d.overview)+'</p><span class="textbook-copy-origin">'+esc(d.origin)+'</span></div>';}
 function distanceBlock(id){const d=decisions.distanceSections?.[id];if(!d)return '';return '<section class="reader-distance-sections" aria-label="距离定义与求法">'+d.sections.map(x=>'<details data-distance-section="'+esc(x.name)+'" data-ui-key="DOT-R4-distance:'+esc(id)+':'+esc(x.name)+'" open><summary><b>'+esc(x.name)+'</b></summary><p class="r80-note">'+text(x.note)+'</p>'+referenceButtons(x.references,'DOT-R4:'+id+':'+x.name)+(id==='kp:21382'&&x.name==='向量公式'?'<details data-ui-key="DOT-R4-original-vector-overview"><summary>原教材向量说明</summary>'+reader.overview(id)+'</details>':'')+'</details>').join('')+chapterButtons(d.sourceChapterPlacements,'DOT-R4:'+id)+(d.relatedKnowledgeIds?.length?'<h3>相关知识</h3><div class=\"r80-example-links\">'+d.relatedKnowledgeIds.map(nid=>'<button type=\"button\" data-method-node=\"'+esc(nid)+'\" data-ui-key=\"DOT-R4-related-knowledge:'+esc(id)+':'+esc(nid)+'\">'+text(node(nid).name)+'</button>').join('')+'</div>':'')+'</section>';}
 function contextBlock(id){const c=decisions.contexts[id];if(!c)return methodHop?.target===id?'<button type="button" data-method-return>返回原入口</button>':'';return '<section class="r80-reading" data-r80-node="'+esc(id)+'">'+(methodHop?.target===id?'<button type="button" data-method-return>返回原入口</button>':'')+(c.approvedMethodIds?.length?'<h3>解题方法</h3><div class="r80-example-links">'+c.approvedMethodIds.map(nid=>'<button type="button" data-method-node="'+esc(nid)+'" data-ui-key="DOT-R3-approved-method:'+esc(id)+':'+esc(nid)+'">进入'+text(node(nid).name)+'方法节点</button>').join('')+'</div>':'')+(c.procedure?.length?'<h3>方法步骤</h3>'+applicationProcedure(c):'')+(c.textbookReferences?.length?'<h3>教材原文</h3>'+referenceButtons(c.textbookReferences,id):'')+'<h3>教案中的说明与例题</h3>'+referenceButtons(c.references,id)+chapterButtons(c.sourceChapterPlacements,id)+'</section>';}
 function decidedCandidates(html){
  if(Object.keys(decisions.candidateDecisions).some(id=>html.includes('data-method-branch="'+id+'"')))html=html.replace('其他方法候选与辨析','方法与应用：采纳及辨析记录');
  for(const [id,d]of Object.entries(decisions.candidateDecisions)){
   const start=html.indexOf('data-method-branch="'+id+'"');if(start<0)continue;
   const a=html.indexOf('<summary>',start),end=html.indexOf('</summary>',a);if(a<0||end<0)continue;
   const thought=d.kind==='existing_thought_family_entry',application=d.kind==='existing_application'||d.kind==='named_application_branch',existingBranch=d.kind==='existing_method_branch',badge=labelRoles[d.labelId]?esc(labelRoles[d.labelId]):d.decisionDisplayRole?esc(d.decisionDisplayRole):d.kind==='knowledge_application_suggestion'?'知识与概念建议':thought?'已复用既有思想或家族入口':d.kind==='knowledge'?'已设为独立知识点':d.kind==='source_record_only'?'保留原题与解答':d.status==='user_decided_application_branch'?'已确定的应用分支':existingBranch?'已复用既有方法分支':application?'已保留为知识应用':d.nodeId?'已设为独立解题方法':'方法类标签';
   html=html.slice(0,a)+html.slice(a,end).replace(/<small>.*?<\/small>/,'<small>'+badge+'</small>')+html.slice(end);
   const body=html.indexOf('<div class="r80-branch-body">',a),at=body+'<div class="r80-branch-body">'.length;
   const button=thought?'<button type="button" data-method-thought-entry="'+esc(d.proposalId)+'" data-ui-key="DOT-R23-thought:'+esc(id)+'">查看'+text(d.name)+'既有入口</button>':(d.kind==='source_record_only'||d.kind==='knowledge_application_suggestion')?'<button type="button" data-method-reference="'+esc(d.primaryContentId)+'" data-ui-key="DOT-R13-source-only:'+esc(id)+'">'+(d.kind==='knowledge_application_suggestion'?'查看来源概念与实例':'查看保留的原题与解答')+'</button>':d.kind==='named_application_branch'?'<button type="button" data-method-reference="'+esc(d.primaryContentId)+'" data-method-application-search="'+esc(d.applicationId)+'" data-ui-key="DOT-R7-decided-application:'+esc(id)+'">查看'+text(d.name)+(d.decisionDisplayRole?'':'具名方案')+'</button>':d.nodeId?'<button type="button" '+((d.batch==='B12'||d.batch==='B13')&&application?'data-r80-read-node':'data-method-node')+'="'+esc(d.nodeId)+'" data-ui-key="B05-node:'+esc(id)+'">'+text(thought?'查看'+d.name+'既有入口':application||existingBranch?'查看'+d.name:'进入'+d.name+'独立节点')+'</button>':'<button type="button" data-method-label="'+esc(d.labelId)+'" data-ui-key="B05-label-candidate:'+esc(id)+'">查看'+text(d.name)+(labelRoles[d.labelId]?'（'+esc(labelRoles[d.labelId])+'）':'方法标签')+'</button>';
   if(d.procedureBoundary==='definition_only'||d.contentHeading){const heading=html.indexOf('<h5>完整题目与解答</h5>',at);if(heading>=0)html=html.slice(0,heading)+'<h5>'+text(d.contentHeading||'来源定义与已有应用')+'</h5>'+html.slice(heading+'<h5>完整题目与解答</h5>'.length);}
   html=html.slice(0,at)+'<p class="r80-note">'+text(d.readingNote||'按本次命名决定采纳；原整理与来源核对状态保留。')+'</p>'+button+html.slice(at);
  }return html;
 }
 function decidedRelations(html){
  if(Object.keys(decisions.relationDecisions).some(id=>html.includes('data-proposal-id="'+id+'"')))html=html.replace('保留提议状态，尚未接入正式图谱。不同材料的使用场景分别列出。','联系保留各自的采纳或提议状态；不同材料的使用场景分别列出。');
  for(const [id,d]of Object.entries(decisions.relationDecisions)){
   const at=html.indexOf('data-proposal-id="'+id+'"');if(at<0)continue;const pos=html.indexOf('>',at)+1;
   html=html.slice(0,pos)+'<p class="r80-note">本条来源用途已接入'+text(d.name||node(d.sourceNodeId)?.name||'已有方法')+'节点；原提案记录保留。</p>'+html.slice(pos);
  }return html;
 }
 // The two views refer to the very same article objects and stable content IDs.
 for(const [id,refs]of Object.entries(decisions.articleReferencesByNodeId)){if(window.READING_DATA.byNodeId[id])throw Error('Method reading identity already exists');window.READING_DATA.byNodeId[id]=refs.map(r=>window.READING_DATA.byNodeId[r.nodeId].find(c=>c.id===r.contentId));if(window.READING_DATA.byNodeId[id].some(c=>!c))throw Error('Missing existing method body');}
 function exerciseEntry(id){return decisions.exercisePresentation19?.entries[id];}
 function exerciseReferences(p){return referenceButtons(p.references,p.id).replace(/data-method-reference=/g,'data-method-exercise-search="'+esc(p.id)+'" data-method-reference=');}
 function exerciseKnowledge(p){return '<div class="r80-example-links">'+p.targetNodeIds.map(id=>'<button type="button" data-method-node="'+esc(id)+'" data-ui-key="P19-knowledge:'+esc(p.id)+':'+esc(id)+'">'+text(node(id).name)+'</button>').join('')+'</div>';}
 function scopedExerciseView(id,html){
  const scoped=decisions.exercisePresentation19;if(!scoped)return html;
  const entries=Object.values(scoped.entries).filter(p=>p.presentationNodeIds.includes(id)),excluded=scoped.excludedRawCandidateIds;
  if(!entries.length&&!excluded.some(x=>html.includes('data-method-branch="'+x+'"')))return html;
  const template=document.createElement('template');template.innerHTML=html;
  const rawIds=new Set([...excluded,...entries.flatMap(p=>p.rawCandidateIds)]),workIds=new Set(entries.map(p=>p.id)),contentIds=new Set(entries.flatMap(p=>p.contentIds));
  for(const e of template.content.querySelectorAll('[data-method-branch]'))if(rawIds.has(e.dataset.methodBranch))e.remove();
  for(const e of template.content.querySelectorAll('[data-application-id]'))if(workIds.has(e.dataset.applicationId))e.remove();
  for(const e of template.content.querySelectorAll('[data-content-id]'))if(contentIds.has(e.dataset.contentId))e.remove();
  for(const e of template.content.querySelectorAll('[data-method-reference]'))if(contentIds.has(e.dataset.methodReference))e.remove();
  for(const e of template.content.querySelectorAll('.r80-method-branches'))if(!e.querySelector('[data-method-branch]'))e.remove();
  for(const e of template.content.querySelectorAll('details[data-ui-key^="r80-candidates:"]'))if(!e.querySelector('[data-method-branch]'))e.remove();
  for(const e of template.content.querySelectorAll('.reader-application-branches'))if(!e.querySelector('[data-application-id]'))e.remove();
  for(const e of template.content.querySelectorAll('.r80-example-links'))if(!e.children.length)e.remove();
  for(const section of template.content.querySelectorAll('section.r80-reading')){
   for(const h of section.querySelectorAll(':scope > h3'))if(h.textContent.startsWith('补充正文')){const count=section.querySelectorAll(':scope > .r80-content').length;h.innerHTML='补充正文 <span>'+count+'</span>';if(!count){const note=h.nextElementSibling;if(note?.classList.contains('r80-note'))note.remove();h.remove();}}
   const h=[...section.querySelectorAll(':scope > h3')].find(e=>e.textContent==='教案中的说明与例题');if(h&&!h.nextElementSibling)h.remove();
   if(!section.children.length)section.remove();
  }
  const visible=entries.filter(p=>p.identity==='visible_solution'&&p.targetNodeIds.includes(id)).map(p=>'<section class="reader-visible-solution" data-visible-solution="'+esc(p.id)+'"><h3>具体求法</h3><button type="button" data-method-reference="'+esc(p.primaryContentId)+'" data-method-exercise-search="'+esc(p.id)+'" data-ui-key="P19-visible-solution:'+esc(id)+'">转化为平行平面间的距离</button></section>').join('');
  const group=entries.length?'<section class="reader-exercises"><details class="r80-proposals" data-exercise-group="'+esc(id)+'" data-ui-key="P19-exercises:'+esc(id)+'"><summary>练习与应用 <span>'+entries.length+'项</span></summary>'+entries.map(p=>'<article data-exercise-id="'+esc(p.id)+'"><h4>'+text(p.title)+' <small>'+esc(p.identityLabel)+'</small></h4>'+(p.currentSourceScopeNote?'<p class="r80-note">'+text(p.currentSourceScopeNote)+'</p>':'')+(!p.targetNodeIds.includes(id)?'<p class="r80-note">对应知识点</p>'+exerciseKnowledge(p):'')+exerciseReferences(p)+'</article>').join('')+'</details></section>':'';
  return template.innerHTML+visible+group;
 }
 function platformMethodOverview(id){const d=decisions.platformMethodDefinitions[id];return '<div class="reader-overview"><p class="reader-description">'+text(d.description)+'</p><span class="textbook-copy-origin">'+esc(d.originLabel)+'</span><section class="textbook-section"><h3>使用条件</h3><ul>'+d.conditions.map(x=>'<li>'+text(x)+'</li>').join('')+'</ul></section></div>';}
 window.TextbookReader={...reader,overview:id=>decisions.platformMethodDefinitions?.[id]?platformMethodOverview(id):id==='method:geometric-dissection'?'<div class="reader-overview"><p class="reader-description">'+text(decisions.descriptionOverrides[id])+'</p><p class="reader-description">面积分支使用面积公式和平方单位；体积分支使用体积公式和立方单位。分割须内部不重叠并覆盖目标，补形相减须满足包含关系；各分支按原题保留适用条件。</p><span class="textbook-copy-origin">编辑概括 · 面积与体积分支</span><details data-ui-key="DOT-R3-R1:volume-overview-context"><summary>体积分支：原教材说明</summary>'+reader.overview(id)+'</details></div>':decisions.distanceSections?.[id]?distanceOverview(id):reader.overview(id),description:id=>decisions.descriptionOverrides?.[id]||reader.description(id),render:id=>scopedExerciseView(id,d7KnowledgeBlock(id)+distanceBlock(id)+labelBlock(id)+decidedRelations(decidedCandidates(reader.render(id)))+applicationBlock(id)+contextBlock(id)),isOpen:()=>reader.isOpen()||own.open,close:()=>{if(reader.isOpen())reader.close();else if(own.open)close();}};
 async function content(cid){if(contentCache.has(cid))return contentCache.get(cid);const nid=index.contentNodeIds[cid];let data;if(nid){data=await window.R80Reader.ensure(nid);}else{if(!loads.has('unassigned'))loads.set('unassigned',fetch('r80/unassigned.json').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json();}));data=await loads.get('unassigned');}const c=data?.contents.find(c=>c.id===cid);if(!c)throw Error('Existing content reference is unavailable');contentCache.set(cid,c);return c;}
