 async function restore(context){await window.KnowledgeReaderNavigation.restore(context.navigation);await new Promise(resolve=>requestAnimationFrame(resolve));for(const r of context.open){const e=document.querySelector('[data-ui-key="'+CSS.escape(r.key)+'"]');if(e)e.open=r.open;}if(innerWidth===context.viewport)for(const r of context.scrolls)document.getElementById(r.id)?.scrollTo({top:r.top,left:r.left,behavior:'instant'});if(context.dialog){stack.splice(0,stack.length,...context.dialog.stack);callerSelector=context.dialog.callerSelector;callerSearch=context.dialog.callerSearch;own.innerHTML=context.dialog.html;if(!own.open)own.showModal();own.scrollTop=context.dialog.scroll;focus(context.selector,own);}else focus(context.selector);window.KnowledgeReaderNavigation.remember();}
