 function updateSearch(){const result=document.getElementById('results'),q=document.getElementById('search').value.normalize('NFKC').trim();result.querySelectorAll('[data-method-label-search],[data-method-application-search]').forEach(e=>e.remove());if(!q)return;for(const l of Object.values(decisions.methodLabels)){if(![l.name,...(l.aliases||[])].some(x=>x.normalize('NFKC').includes(q)))continue;const b=document.createElement('button');b.type='button';b.dataset.methodLabel=l.id;b.dataset.methodLabelSearch='true';b.dataset.uiKey='B05-search-label:'+l.id;b.innerHTML='<span class="search-result-title"><span class="type-badge">'+esc(labelRoles[l.id]||'方法类标签')+'</span><span>'+esc(l.name)+'</span></span><small>'+esc(l.chapterIds.map(id=>node(id).name).join(' / '))+'</small>';const caption=result.querySelector('.search-caption');if(caption?.textContent.includes('未找到这个名称'))caption.textContent=labelRoles[l.id]?'思想标签':'方法类标签';result.append(b);result.hidden=false;}}
 const updateLabels=updateSearch;updateSearch=function(){updateLabels();const result=document.getElementById('results'),q=document.getElementById('search').value.normalize('NFKC').trim();if(!q)return;for(const a of Object.values(decisions.applicationBranches||{})){if(exerciseEntry(a.id))continue;if(![a.name,...a.aliases].some(x=>x.includes(q)))continue;const b=document.createElement('button');b.type='button';b.dataset.methodReference=a.primaryContentId;b.dataset.methodApplicationSearch=a.id;b.dataset.uiKey='B14-search-application:'+a.id;b.innerHTML='<span class="search-result-title"><span class="type-badge">'+esc(a.decisionDisplayRole||'应用分支')+'</span><span>'+esc(a.name)+'</span></span><small>'+esc(window.NETWORK?.nodes.find(n=>n.id===a.primaryNodeId)?.name||'应用分支')+' · '+esc(a.status==='user_decided_application_branch'?'已确定':'知识应用，候选身份保留')+' · '+esc((a.sourceIds||[]).join('、'))+'</small>';const caption=result.querySelector('.search-caption');if(caption?.textContent.includes('未找到这个名称'))caption.textContent='应用分支';result.append(b);result.hidden=false;}};
 const updateUnscopedSearch=updateSearch;updateSearch=function(){updateUnscopedSearch();const result=document.getElementById('results'),q=document.getElementById('search').value.normalize('NFKC').trim();result.querySelectorAll('[data-method-exercise-search]').forEach(e=>e.remove());if(!q)return;for(const p of Object.values(decisions.exercisePresentation19.entries)){if(![...p.aliases,...p.references.map(r=>r.originalTitle)].some(x=>x.normalize('NFKC').includes(q)))continue;const b=document.createElement('button');b.type='button';b.dataset.methodReference=p.primaryContentId;b.dataset.methodExerciseSearch=p.id;b.dataset.uiKey='P19-search:'+p.id;b.innerHTML='<span class="search-result-title"><span class="type-badge">'+esc(p.identityLabel)+'</span><span>'+text(p.title)+'</span></span><small>'+esc(p.targetNodeIds.map(id=>node(id).name).join(' / '))+'</small>';const caption=result.querySelector('.search-caption');if(caption?.textContent.includes('未找到这个名称'))caption.textContent='练习与应用';result.append(b);result.hidden=false;}};
